 1	package br.com.loja.pedidos.pedido;
 2	
 3	import java.sql.ResultSet;
 4	import java.sql.SQLException;
 5	import java.time.Instant;
 6	import java.time.OffsetDateTime;
 7	import java.time.ZoneOffset;
 8	import java.util.Arrays;
 9	import java.util.List;
10	import java.util.Optional;
11	
12	import org.springframework.jdbc.core.simple.JdbcClient;
13	import org.springframework.jdbc.support.GeneratedKeyHolder;
14	import org.springframework.jdbc.support.KeyHolder;
15	import org.springframework.stereotype.Repository;
16	
17	import br.com.loja.pedidos.checkout.Resumo;
18	import br.com.loja.pedidos.cliente.HistoricoCompras;
19	import tools.jackson.databind.ObjectMapper;
20	
21	@Repository
22	public class PedidoRepositorio implements HistoricoCompras {
23	
24	    private static final List<String> SITUACOES_PAGAS = Arrays.stream(SituacaoPedido.values())
25	            .filter(SituacaoPedido::pago).map(Enum::name).toList();
26	
27	    private final JdbcClient jdbc;
28	    private final ObjectMapper json;
29	
30	    public PedidoRepositorio(JdbcClient jdbc, ObjectMapper json) {
31	        this.jdbc = jdbc;
32	        this.json = json;
33	    }
34	
35	    public long inserir(String cpf, Instant criadoEm, Resumo resumo, List<ItemPedido> itens) {
36	        KeyHolder chave = new GeneratedKeyHolder();
37	        jdbc.sql("INSERT INTO pedido (cpf, situacao, criado_em, resumo) VALUES (?, ?, ?, ?)")
38	                .param(cpf).param(SituacaoPedido.AGUARDANDO_PAGAMENTO.name()).param(paraBanco(criadoEm))
39	                .param(json.writeValueAsString(resumo))
40	                .update(chave, "id");
41	        long id = chave.getKeyAs(Number.class).longValue();
42	        for (int i = 0; i < itens.size(); i++) {
43	            jdbc.sql("INSERT INTO item_pedido (pedido_id, sku, quantidade, posicao) VALUES (?, ?, ?, ?)")
44	                    .param(id).param(itens.get(i).sku()).param(itens.get(i).quantidade()).param(i).update();
45	        }
46	        return id;
47	    }
48	
49	    public Optional<Pedido> buscar(long id) {
50	        return jdbc.sql("SELECT * FROM pedido WHERE id = ?").param(id).query(this::mapear).optional();
51	    }
52	
53	
54	    public Optional<Pedido> travar(long id) {
55	        return jdbc.sql("SELECT * FROM pedido WHERE id = ? FOR UPDATE").param(id).query(this::mapear).optional();
56	    }
57	
58	    public void alterarSituacao(long id, SituacaoPedido situacao) {
59	        jdbc.sql("UPDATE pedido SET situacao = ? WHERE id = ?").param(situacao.name()).param(id).update();
60	    }
61	
62	    public void registrarPagamento(long id, String idTransacao, Instant pagoEm) {
63	        jdbc.sql("UPDATE pedido SET situacao = ?, id_transacao = ?, pago_em = ? WHERE id = ?")
64	                .param(SituacaoPedido.PAGO.name()).param(idTransacao).param(paraBanco(pagoEm)).param(id).update();
65	    }
66	
67	    public void registrarEnvio(long id, String codigoRastreio) {
68	        jdbc.sql("UPDATE pedido SET situacao = ?, codigo_rastreio = ? WHERE id = ?")
69	                .param(SituacaoPedido.ENVIADO.name()).param(codigoRastreio).param(id).update();
70	    }
71	
72	    @Override
73	    public boolean jaComprou(String cpf) {
74	        return jdbc.sql("SELECT COUNT(*) FROM pedido WHERE cpf = :cpf AND situacao IN (:situacoes)")
75	                .param("cpf", cpf).param("situacoes", SITUACOES_PAGAS)
76	                .query(Long.class).single() > 0;
77	    }
78	
79	    private Pedido mapear(ResultSet rs, int linha) throws SQLException {
80	        long id = rs.getLong("id");
81	        List<ItemPedido> itens = jdbc.sql("SELECT sku, quantidade FROM item_pedido WHERE pedido_id = ? ORDER BY posicao")
82	                .param(id).query((r, n) -> new ItemPedido(r.getString("sku"), r.getInt("quantidade"))).list();
83	        return new Pedido(id, rs.getString("cpf"), SituacaoPedido.valueOf(rs.getString("situacao")),
84	                rs.getObject("criado_em", OffsetDateTime.class).toInstant(),
85	                json.readValue(rs.getString("resumo"), Resumo.class), itens, rs.getString("codigo_rastreio"),
86	                rs.getString("id_transacao"));
87	    }
88	
89	    private static OffsetDateTime paraBanco(Instant instante) {
90	        return instante.atOffset(ZoneOffset.UTC);
91	    }
92	}
