 3	import java.math.BigDecimal;
 4	
 5	public record Resumo(
 6	        BigDecimal subtotalProdutos,
 7	        BigDecimal descontoCupom,
 8	        BigDecimal frete,
 9	        int prazoEntregaDias,
10	        BigDecimal seguro,
11	        BigDecimal ajustePagamento,
12	        BigDecimal totalFinal,
13	        int parcelas,
14	        BigDecimal valorParcela,
15	        BigDecimal creditoProximaCompra,
16	        boolean brinde) {
17	}
 1	package br.com.loja.pedidos.cliente;
 2	
 3	import java.math.BigDecimal;
 4	import java.util.Optional;
 5	
 6	import org.springframework.dao.DuplicateKeyException;
 7	import org.springframework.jdbc.core.simple.JdbcClient;
 8	import org.springframework.stereotype.Repository;
 9	
10	@Repository
11	public class ClienteRepositorio {
12	
13	    private final JdbcClient jdbc;
14	
15	    public ClienteRepositorio(JdbcClient jdbc) {
16	        this.jdbc = jdbc;
17	    }
18	
19	
20	    public void garantir(String cpf, String email) {
21	        try {
22	            jdbc.sql("INSERT INTO cliente (cpf, email, saldo_credito) SELECT ?, ?, 0 "
23	                    + "WHERE NOT EXISTS (SELECT 1 FROM cliente WHERE cpf = ?)")
24	                    .param(cpf).param(email).param(cpf).update();
25	        } catch (DuplicateKeyException e) {
26	
27	        }
28	    }
29	
30	    public Optional<BigDecimal> saldo(String cpf) {
31	        return jdbc.sql("SELECT saldo_credito FROM cliente WHERE cpf = ?").param(cpf).query(BigDecimal.class).optional()
32	                .map(saldo -> saldo.setScale(2));
33	    }
34	
35	    public void alterarSaldo(String cpf, BigDecimal variacao) {
36	        jdbc.sql("UPDATE cliente SET saldo_credito = saldo_credito + ? WHERE cpf = ?").param(variacao).param(cpf).update();
37	    }
38	}

