37	        jdbc.sql("INSERT INTO pedido (cpf, situacao, criado_em, resumo) VALUES (?, ?, ?, ?)")
38	                .param(cpf).param(SituacaoPedido.AGUARDANDO_PAGAMENTO.name()).param(paraBanco(criadoEm))
39	                .param(json.writeValueAsString(resumo))
