42	        for (int i = 0; i < itens.size(); i++) {
43	            jdbc.sql("INSERT INTO item_pedido (pedido_id, sku, quantidade, posicao) VALUES (?, ?, ?, ?)")
44	                    .param(id).param(itens.get(i).sku()).param(itens.get(i).quantidade()).param(i).update();
