 12	import org.springframework.stereotype.Service;
 13	import org.springframework.transaction.PlatformTransactionManager;
 14	import org.springframework.transaction.annotation.Transactional;
 15	import org.springframework.transaction.support.TransactionTemplate;
 16	
 17	import br.com.loja.pedidos.aviso.AvisoRepositorio;
 18	import br.com.loja.pedidos.aviso.TipoAviso;
 19	import br.com.loja.pedidos.catalogo.Produto;
 20	import br.com.loja.pedidos.catalogo.ProdutoRepositorio;
