 27	
 28	@Service
 29	public class PedidoService {
 30	
 31	    private static final Duration PRAZO_PAGAMENTO = Duration.ofHours(48);
 32	
 33	    private final CalculadoraResumo calculadora;
 34	    private final PedidoRepositorio pedidos;
 35	    private final ProdutoRepositorio produtos;
 36	    private final ClienteRepositorio clientes;
 37	    private final AvisoRepositorio avisos;
 38	    private final List<EfeitoPagamento> efeitosPagamento;
 39	    private final Clock relogio;
 40	    private final TransactionTemplate transacao;
 41	
 42	    public PedidoService(CalculadoraResumo calculadora, PedidoRepositorio pedidos, ProdutoRepositorio produtos,
 43	            ClienteRepositorio clientes, AvisoRepositorio avisos, List<EfeitoPagamento> efeitosPagamento,
 44	            Clock relogio, PlatformTransactionManager transacoes) {
 45	        this.calculadora = calculadora;
 46	        this.pedidos = pedidos;
 47	        this.produtos = produtos;
 48	        this.clientes = clientes;
 49	        this.avisos = avisos;
 50	        this.efeitosPagamento = efeitosPagamento;
 51	        this.relogio = relogio;
 52	        this.transacao = new TransactionTemplate(transacoes);
 53	    }
 54	
 55	    public Pedido registrar(JsonNode dados) {
 56	
 57	        Checkout checkout = calculadora.calcular(dados);
 58	        return transacao.execute(status -> gravar(checkout));
 59	    }
 60	
 61	    private Pedido gravar(Checkout checkout) {
 62	        clientes.garantir(checkout.cpf(), checkout.email());
 63	        List<ItemPedido> itens = checkout.itens().stream()
 64	                .map(item -> new ItemPedido(item.produto().sku(), item.quantidade())).toList();
 65	        long id = pedidos.inserir(checkout.cpf(), Instant.now(relogio).truncatedTo(ChronoUnit.SECONDS),
 66	                checkout.resumo(), itens);
 67	        return pedidos.buscar(id).orElseThrow();
 68	    }
 69	
 70	    public Pedido consultar(String id) {
 71	        return pedidos.buscar(lerId(id)).orElseThrow(PedidoService::naoEncontrado);
 72	    }
 73	
 74	
 75	
 76	
 77	
 78	    @Transactional(noRollbackFor = ErroNegocio.class)
 79	    public Pedido pagar(String id, String idTransacao, Instant pagoEm) {
 80	        Pedido pedido = travar(id);
 81	        if (idTransacao != null && idTransacao.equals(pedido.idTransacao())) {
 82	            return pedido;
 83	        }
 84	        if (!pedido.situacao().podeIrPara(SituacaoPedido.PAGO)) {
 85	            throw ErroNegocio.conflito("OPERACAO_NAO_PERMITIDA");
 86	        }
 87	        if (idTransacao == null || idTransacao.isBlank() || pagoEm == null) {
 88	            throw ErroNegocio.invalido("PEDIDO_INVALIDO");
 89	        }
 90	        if (pagoEm.isAfter(pedido.criadoEm().plus(PRAZO_PAGAMENTO))) {
 91	            cancelarSemPagamento(pedido);
 92	            throw ErroNegocio.conflito("PEDIDO_EXPIRADO");
 93	        }
 94	        if (!baixarEstoque(pedido)) {
 95	            cancelarSemPagamento(pedido);
 96	            throw ErroNegocio.conflito("ESTOQUE_INSUFICIENTE");
 97	        }
 98	        pedidos.registrarPagamento(pedido.id(), idTransacao, pagoEm);
 99	        Pedido pago = pedidos.buscar(pedido.id()).orElseThrow();
100	        efeitosPagamento.forEach(efeito -> efeito.aoConfirmar(pago));
101	        return pago;
102	    }
103	
104	    @Transactional
105	    public Pedido enviar(String id, String codigoRastreio) {
106	        Pedido pedido = travar(id);
107	        exigirTransicao(pedido, SituacaoPedido.ENVIADO);
108	        if (codigoRastreio == null || codigoRastreio.isBlank()) {
109	            throw ErroNegocio.invalido("PEDIDO_INVALIDO");
110	        }
111	        pedidos.registrarEnvio(pedido.id(), codigoRastreio);
112	        avisos.registrar(pedido.cpf(), TipoAviso.PEDIDO_ENVIADO, pedido.id());
113	        return pedidos.buscar(pedido.id()).orElseThrow();
114	    }
115	
116	    @Transactional
117	    public Pedido entregar(String id) {
118	        Pedido pedido = travar(id);
119	        exigirTransicao(pedido, SituacaoPedido.ENTREGUE);
120	        pedidos.alterarSituacao(pedido.id(), SituacaoPedido.ENTREGUE);
121	        return pedidos.buscar(pedido.id()).orElseThrow();
122	    }
123	
124	    @Transactional
125	    public Pedido cancelar(String id) {
126	        Pedido pedido = travar(id);
127	        exigirTransicao(pedido, SituacaoPedido.CANCELADO);
128	        if (pedido.situacao().pago()) {
129	            produtos.travar(pedido.itens().stream().map(ItemPedido::sku).toList());
130	            pedido.itens().forEach(item -> produtos.alterarEstoque(item.sku(), item.quantidade()));
131	            efeitosPagamento.forEach(efeito -> efeito.aoCancelarPedidoPago(pedido));
132	        }
133	        pedidos.alterarSituacao(pedido.id(), SituacaoPedido.CANCELADO);
134	        avisos.registrar(pedido.cpf(), TipoAviso.PEDIDO_CANCELADO, pedido.id());
135	        return pedidos.buscar(pedido.id()).orElseThrow();
136	    }
137	
138	    private void cancelarSemPagamento(Pedido pedido) {
139	        pedidos.alterarSituacao(pedido.id(), SituacaoPedido.CANCELADO);
140	        avisos.registrar(pedido.cpf(), TipoAviso.PEDIDO_CANCELADO, pedido.id());
141	    }
142	
143	
144	    private boolean baixarEstoque(Pedido pedido) {
145	        Map<String, Produto> travados = produtos.travar(pedido.itens().stream().map(ItemPedido::sku).toList()).stream()
146	                .collect(Collectors.toMap(Produto::sku, Function.identity()));
147	        boolean haEstoque = pedido.itens().stream()
148	                .allMatch(item -> travados.get(item.sku()).estoque() >= item.quantidade());
149	        if (haEstoque) {
150	            pedido.itens().forEach(item -> produtos.alterarEstoque(item.sku(), -item.quantidade()));
151	        }
152	        return haEstoque;
153	    }
154	
155	    private Pedido travar(String id) {
156	        return pedidos.travar(lerId(id)).orElseThrow(PedidoService::naoEncontrado);
157	    }
158	
159	    private static void exigirTransicao(Pedido pedido, SituacaoPedido destino) {
160	        if (!pedido.situacao().podeIrPara(destino)) {
161	            throw ErroNegocio.conflito("OPERACAO_NAO_PERMITIDA");
162	        }
163	    }
164	
165	    private static long lerId(String id) {
166	        return Identificador.ler(id).orElseThrow(PedidoService::naoEncontrado);
167	    }
168	
169	    private static ErroNegocio naoEncontrado() {
170	        return ErroNegocio.naoEncontrado("PEDIDO_NAO_ENCONTRADO");
171	    }
172	}
