111	        pedidos.registrarEnvio(pedido.id(), codigoRastreio);
112	        avisos.registrar(pedido.cpf(), TipoAviso.PEDIDO_ENVIADO, pedido.id());
113	        return pedidos.buscar(pedido.id()).orElseThrow();
114	    }
