116	    @Transactional
117	    public Pedido entregar(String id) {
118	        Pedido pedido = travar(id);
119	        exigirTransicao(pedido, SituacaoPedido.ENTREGUE);
120	        pedidos.alterarSituacao(pedido.id(), SituacaoPedido.ENTREGUE);
121	        return pedidos.buscar(pedido.id()).orElseThrow();
122	    }
123	
124	    @Transactional
125	    public Pedido cancelar(String id) {
126	        Pedido pedido = travar(id);
127	        exigirTransicao(pedido, SituacaoPedido.CANCELADO);
128	        if (pedido.situacao().pago()) {
129	            produtos.travar(pedido.itens().stream().map(ItemPedido::sku).toList());
130	            pedido.itens().forEach(item -> produtos.alterarEstoque(item.sku(), item.quantidade()));
131	            efeitosPagamento.forEach(efeito -> efeito.aoCancelarPedidoPago(pedido));
132	        }
133	        pedidos.alterarSituacao(pedido.id(), SituacaoPedido.CANCELADO);
134	        avisos.registrar(pedido.cpf(), TipoAviso.PEDIDO_CANCELADO, pedido.id());
135	        return pedidos.buscar(pedido.id()).orElseThrow();
136	    }
