138	    private void cancelarSemPagamento(Pedido pedido) {
139	        pedidos.alterarSituacao(pedido.id(), SituacaoPedido.CANCELADO);
140	        avisos.registrar(pedido.cpf(), TipoAviso.PEDIDO_CANCELADO, pedido.id());
141	    }
142	
143	
144	    private boolean baixarEstoque(Pedido pedido) {
145	        Map<String, Produto> travados = produtos.travar(pedido.itens().stream().map(ItemPedido::sku).toList()).stream()
146	                .collect(Collectors.toMap(Produto::sku, Function.identity()));
147	        boolean haEstoque = pedido.itens().stream()
148	                .allMatch(item -> travados.get(item.sku()).estoque() >= item.quantidade());
149	        if (haEstoque) {
150	            pedido.itens().forEach(item -> produtos.alterarEstoque(item.sku(), -item.quantidade()));
151	        }
152	        return haEstoque;
153	    }
